/* ============================================================
   HOLLOW CROWN — SKIRMISH
   Portrait-first mobile UI. No external fonts or assets.
   ============================================================ */

:root {
  --bg: #08070b;
  --panel: #121019;
  --panel-2: #191521;
  --gold: #d8b56c;
  --gold-hi: #efd49a;
  --gold-dim: #8a7442;
  --teal: #7fc4b6;
  --red: #d06b62;
  --text: #ece5d8;
  --muted: #9b93a4;
  --line: rgba(216, 181, 108, 0.22);
  --line-soft: rgba(255, 255, 255, 0.08);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--text);
  overscroll-behavior: none;
}

body {
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  touch-action: manipulation;
  overflow: hidden;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}

#app {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
}

.screen {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
}

.screen.active {
  display: flex;
}

.hidden {
  display: none !important;
}

/* ============================================================
   HOME
   ============================================================ */

#home {
  align-items: center;
  justify-content: center;
  padding: calc(24px + var(--safe-top)) 24px calc(24px + var(--safe-bottom));
  overflow: hidden;
  background:
    radial-gradient(120% 70% at 50% 10%, #191322 0%, #0b0910 46%, #07060a 100%);
}

.home-glow {
  position: absolute;
  width: 120vw;
  height: 120vw;
  max-width: 760px;
  max-height: 760px;
  left: 50%;
  top: 6%;
  transform: translateX(-50%);
  background: radial-gradient(circle, rgba(216, 181, 108, 0.16), rgba(216, 181, 108, 0.04) 42%, transparent 68%);
  filter: blur(6px);
  animation: breathe 6s ease-in-out infinite;
  pointer-events: none;
}

@keyframes breathe {
  0%, 100% { opacity: 0.7; transform: translateX(-50%) scale(0.96); }
  50% { opacity: 1; transform: translateX(-50%) scale(1.04); }
}

.home-inner {
  position: relative;
  z-index: 1;
  width: min(100%, 380px);
  text-align: center;
}

.crest {
  width: 68px;
  height: 68px;
  margin: 0 auto 6px;
  color: var(--gold);
  opacity: 0.9;
  filter: drop-shadow(0 0 18px rgba(216, 181, 108, 0.35));
}

.crest svg {
  width: 100%;
  height: 100%;
}

.kicker {
  margin: 0;
  font-size: 9px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--gold-dim);
}

h1 {
  margin: 14px 0 0;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
  font-size: clamp(52px, 15.5vw, 76px);
  line-height: 0.84;
  letter-spacing: 0.045em;
  text-shadow: 0 8px 40px rgba(0, 0, 0, 0.8);
}

h1 span {
  color: var(--gold);
}

.tagline {
  margin: 20px 0 0;
  font-family: Georgia, "Times New Roman", serif;
  font-style: italic;
  font-size: 14px;
  line-height: 1.55;
  color: var(--muted);
}

.menu {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 30px;
}

.foot {
  margin: 26px 0 0;
  font-size: 9px;
  letter-spacing: 0.28em;
  color: rgba(155, 147, 164, 0.6);
}

/* ============================================================
   BUTTONS
   ============================================================ */

.btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 50px;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, #1a1622, #121019);
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: transform 0.08s ease, filter 0.12s ease, opacity 0.12s ease;
}

.btn:active:not(:disabled) {
  transform: scale(0.975);
}

.btn.primary {
  border-color: rgba(239, 212, 154, 0.7);
  background: linear-gradient(180deg, #e6c681, #b8934b);
  color: #1a1206;
  box-shadow: 0 6px 24px rgba(216, 181, 108, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.35);
}

.btn.ghost {
  border-color: var(--line-soft);
  background: rgba(255, 255, 255, 0.025);
  color: var(--muted);
}

.btn:disabled {
  opacity: 0.32;
  cursor: default;
}

.icon-btn {
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  border: 1px solid var(--line-soft);
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font-size: 16px;
  line-height: 1;
  transition: transform 0.08s ease, color 0.12s ease;
}

.icon-btn:active {
  transform: scale(0.94);
}

.icon-btn.muted {
  color: rgba(155, 147, 164, 0.4);
}

/* ============================================================
   BATTLE SHELL
   ============================================================ */

#battle {
  padding: calc(8px + var(--safe-top)) 10px calc(8px + var(--safe-bottom));
  gap: 7px;
  background:
    radial-gradient(110% 50% at 50% 0%, #15111d 0%, #0a090e 55%, #07060a 100%);
}

.hud {
  display: flex;
  align-items: center;
  gap: 8px;
}

.hud-mid {
  flex: 1;
  min-width: 0;
  text-align: center;
}

.hud-mid span {
  display: block;
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--gold-dim);
}

.hud-mid strong {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 15px;
  font-weight: 400;
  letter-spacing: 0.02em;
}

.objective {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 3px;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: var(--muted);
}

#hud-turn {
  color: var(--gold-dim);
  white-space: nowrap;
}

.battle-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.board-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

#board {
  display: block;
  border-radius: 14px;
  background: #0a0910;
  box-shadow:
    0 0 0 1px rgba(216, 181, 108, 0.16),
    0 18px 50px rgba(0, 0, 0, 0.55);
  touch-action: none;
}

.battle-side {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* ============================================================
   HERO CARDS
   ============================================================ */

.unit-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.hero-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  min-height: 58px;
  padding: 7px 8px;
  text-align: left;
  border-radius: 10px;
  border: 1px solid var(--line-soft);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015));
  color: var(--text);
  transition: opacity 0.15s ease, border-color 0.15s ease, transform 0.08s ease;
}

.hero-card:active {
  transform: scale(0.985);
}

.hero-card.selected {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px var(--gold), 0 0 18px rgba(216, 181, 108, 0.16);
}

.hero-card.spent {
  opacity: 0.42;
}

.hero-card.fallen {
  opacity: 0.26;
}

.hero-card.fallen .hc-name {
  text-decoration: line-through;
}

.hc-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 4px;
}

.hc-name {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.hc-hpnum {
  flex: 0 0 auto;
  font-size: 9px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.hc-bar {
  height: 4px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.08);
}

.hc-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #8fc9a5, #6eae8a);
  transition: width 0.25s ease, background 0.25s ease;
}

.hc-bar i.mid {
  background: linear-gradient(90deg, #d8b56c, #b8934b);
}

.hc-bar i.low {
  background: linear-gradient(90deg, #d06b62, #a84d47);
}

.hc-state {
  font-size: 7.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hero-card.selected .hc-state {
  color: var(--gold);
}

.controls {
  display: grid;
  grid-template-columns: 1fr 1.45fr;
  gap: 8px;
}

.controls .btn {
  min-height: 50px;
}

/* ============================================================
   BOARD OVERLAYS
   ============================================================ */

.hint {
  position: absolute;
  left: 50%;
  bottom: 10px;
  transform: translateX(-50%);
  max-width: 92%;
  padding: 6px 12px;
  border-radius: 99px;
  background: rgba(7, 6, 10, 0.82);
  border: 1px solid var(--line-soft);
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.05em;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.25s ease;
}

.hint.gone {
  opacity: 0;
}

.banner {
  position: absolute;
  left: 0;
  right: 0;
  top: 42%;
  transform: translateY(-50%) scale(0.96);
  text-align: center;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(24px, 8vw, 40px);
  letter-spacing: 0.14em;
  color: var(--gold-hi);
  text-shadow: 0 4px 30px rgba(0, 0, 0, 0.95), 0 0 26px rgba(216, 181, 108, 0.35);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.banner.show {
  opacity: 1;
  transform: translateY(-50%) scale(1);
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 52px;
  transform: translate(-50%, 8px);
  max-width: 90%;
  padding: 8px 14px;
  border-radius: 99px;
  background: rgba(20, 16, 26, 0.94);
  border: 1px solid var(--line);
  color: var(--text);
  font-size: 11px;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ============================================================
   OVERLAY / SHEETS
   ============================================================ */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(18px + var(--safe-top)) 18px calc(18px + var(--safe-bottom));
  background: rgba(5, 4, 8, 0.78);
  -webkit-backdrop-filter: blur(7px);
  backdrop-filter: blur(7px);
  animation: fadeIn 0.18s ease;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.sheet {
  width: min(100%, 380px);
  max-height: 88dvh;
  overflow-y: auto;
  padding: 22px 20px 20px;
  border-radius: 18px;
  border: 1px solid var(--line);
  background:
    radial-gradient(120% 60% at 50% 0%, #201a2a 0%, #14111b 60%, #100e15 100%);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  animation: rise 0.2s ease;
}

@keyframes rise {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
  to { opacity: 1; transform: none; }
}

.sheet h2 {
  margin: 8px 0 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 30px;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--gold-hi);
}

.sheet p {
  margin: 10px 0 0;
  font-size: 12px;
  line-height: 1.55;
  color: var(--muted);
}

.sheet .rules {
  margin: 14px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.sheet .rules li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  font-size: 12px;
  line-height: 1.45;
  color: var(--text);
}

.rule-num {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
}

.sheet-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 20px;
}

.sheet-actions.row {
  flex-direction: row;
}

.sheet-actions.row .btn {
  flex: 1;
}

.stats {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 16px;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--line-soft);
  background: rgba(255, 255, 255, 0.025);
}

.stats div {
  text-align: center;
}

.stats strong {
  display: block;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 22px;
  font-weight: 400;
  color: var(--gold-hi);
}

.stats span {
  display: block;
  margin-top: 2px;
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.notice {
  margin-top: 14px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid rgba(127, 196, 182, 0.35);
  background: rgba(127, 196, 182, 0.08);
  color: var(--teal);
  font-size: 11px;
  line-height: 1.45;
}

.upgrade-label {
  margin-top: 20px !important;
  font-size: 8px !important;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold-dim) !important;
}

.upgrade {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin-top: 8px;
  padding: 11px 12px;
  text-align: left;
  border-radius: 12px;
  border: 1px solid var(--line-soft);
  background: rgba(255, 255, 255, 0.025);
  transition: border-color 0.12s ease, background 0.12s ease, transform 0.08s ease;
}

.upgrade:active {
  transform: scale(0.985);
}

.upgrade.selected {
  border-color: var(--gold);
  background: rgba(216, 181, 108, 0.1);
}

.up-icon {
  flex: 0 0 auto;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: rgba(216, 181, 108, 0.06);
  color: var(--gold);
  font-size: 17px;
}

.upgrade strong {
  display: block;
  font-size: 12px;
  letter-spacing: 0.03em;
}

.upgrade small {
  display: block;
  margin-top: 2px;
  font-size: 10px;
  line-height: 1.35;
  color: var(--muted);
}

/* ============================================================
   LANDSCAPE
   ============================================================ */

@media (orientation: landscape) and (max-height: 560px) {
  #battle {
    padding: calc(6px + var(--safe-top)) calc(10px + env(safe-area-inset-right, 0px)) calc(6px + var(--safe-bottom)) calc(10px + env(safe-area-inset-left, 0px));
    gap: 5px;
  }

  .battle-body {
    flex-direction: row;
    gap: 10px;
  }

  .battle-side {
    width: 208px;
    justify-content: flex-end;
  }

  .unit-strip {
    grid-template-columns: 1fr;
  }

  .hero-card {
    min-height: 46px;
    padding: 6px 8px;
  }

  .controls {
    grid-template-columns: 1fr;
  }

  .controls .btn {
    min-height: 42px;
  }

  .hud-mid strong {
    font-size: 13px;
  }

  .icon-btn {
    width: 38px;
    height: 38px;
  }

  .hint {
    bottom: 7px;
    font-size: 9px;
  }

  .toast {
    bottom: 42px;
  }
}

@media (max-height: 620px) and (orientation: portrait) {
  .hero-card {
    min-height: 52px;
    padding: 6px 7px;
  }

  .hc-state {
    display: none;
  }

  .controls .btn {
    min-height: 46px;
  }

  .tagline {
    margin-top: 14px;
  }

  .menu {
    margin-top: 22px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

content.text:
I have a stray `@media (max-height: 620px) and (orientation: portrait)` with a typo `orientation: portrait` should be `orientation: portrait` yes valid. Wait, CSS syntax: `@media (max-height: 620px) and (orientation: portrait)` is valid. Fine.

But I have `.battle-side` in portrait containing unit-strip and controls. In the 620px portrait media, hiding .hc-state. Fine.

Potential issue: `.hint` is absolute inside board-wrap, but board canvas may be smaller than wrap; hint bottom relative to wrap not canvas. Fine.

Now the game JS. This is the big part. Let me write carefully.

Key considerations:
- Use `const G` global state.
- DOM caching.
- Render loop.
- Async flows with sleep. Need to guard against restart during async: use `G.runToken` incremented on stage start; each async loop captures token and aborts if changed. Important when player restarts mid-enemy turn or leaves.

Let me design functions and variables:

```js
const BOARD = 6;
const SAVE_KEY = 'hollow-crown-skirmish-v1';
const MUTE_KEY = 'hollow-crown-skirmish-muted';

const HERO_TYPES = {
  warden: {name:'Warden', hp:11, atk:3, move:1, range:1, color:'#d8b56c', icon:'warden'},
  ranger: {name:'Ranger', hp:7, atk:2, move:2, range:2, color:'#7fc4b6', icon:'ranger'},
  hexblade:{name:'Hexblade', hp:8, atk:4, move:1, range:1, color:'#b49bdd', icon:'hexblade'},
};
const ENEMY_TYPES = {
  ghoul: {name:'Ghoul', hp:5, atk:2, move:1, range:1, color:'#b86b62', icon:'ghoul'},
  wraith:{name:'Wraith', hp:4, atk:2, move:2, range:1, color:'#8b7fb5', icon:'wraith'},
  archer:{name:'Bone Archer', hp:4, atk:2, move:1, range:2, color:'#c9a86a', icon:'archer'},
  boss: {name:'Hollow King', hp:15, atk:4, move:1, range:1, color:'#d06b62', icon:'boss'},
};
```

Stage data:
```js
const STAGES = [
  { name:'The Ashen Gate', enemies:[['ghoul',2,0],['ghoul',4,1]] },
  { name:'The Weeping Wood', enemies:[['ghoul',1,0],['ghoul',4,0],['wraith',2,1]] },
  { name:'The Bone Choir', enemies:[['archer',1,0],['archer',4,1],['wraith',2,0],['wraith',5,2]] },
  { name:'The Broken Keep', enemies:[['boss',2,1],['ghoul',4,0],['ghoul',1,2]] },
  { name:'The Hollow Throne', enemies:[['boss',2,1],['archer',0,0],['archer',5,0],['wraith',3,2]] },
];
```
Player spawns per stage:
- 2 heroes: warden (2,5), ranger (3,4)
- 3: warden (1,5), hexblade (2,4), ranger (4,5)
Check stage 2 enemy at (5,2) and spawn (4,5) fine.

Balance concern: Stage 2 has 4 enemies, 2 archers range 2 + 2 wraiths move 2. Heroes start near bottom. Enemies move down. Player has 3 heroes + 2 upgrades by then (after stage 0 and 1). If player picks attack twice: warden 5 atk, ranger 4, hex 6; total 15 dmg/turn. Enemy total HP 4+4+4+4=16. Fine. Enemy dmg 2 each. Should be manageable.

Boss 15 HP, 4 atk. Stage 4 has boss + archer + archer + wraith = 27 HP. Player by then 4 upgrades, e.g. atk x4: warden 7, ranger 6, hex 8 = 21 dmg/turn. 2 turns to clear if focus; boss hits 4/turn. Heroes total HP 26+. Fine.

Stage 1 (idx1) 3 enemies: ghoul 5, ghoul 5, wraith 4 = 14 HP; 3 heroes with 1 upgrade. Fine.

Enemy AI should be aggressive but not overwhelming.

Now unit creation:
```js
let uid = 1;
function createHero(type, x, y) {
  const b = HERO_TYPES[type];
  const maxHp = b.hp + G.upgrades.hp*2;
  return {id: 'h'+uid++, side:'hero', type, name:b.name, x,y,rx:x,ry:y, hp:maxHp, maxHp, atk:b.atk+G.upgrades.atk, move:b.move+G.upgrades.move, range:b.range, color:b.color, icon:b.icon, alive:true, moved:false, attacked:false, spent:false, bob:Math.random()*Math.PI*2, flash:0, deathT:0};
}
```
Enemies with fixed stats. Note G.upgrades is reset/new run.

`G`:
```js
const G = {
  screen:'home',
  stageIndex:0,
  turn:1,
  phase:'player',
  units:[],
  selectedId:null,
  activeEnemyId:null,
  busy:false,
  upgrades:{atk:0,hp:0,move:0},
  floaters:[],
  shake:0,
  token:0,
  stats:{fallen:0},
  runTurns:0,
  hintTimer:null,
  bannerTimer:null,
  toastTimer:null,
};
```

Load settings muted from localStorage.

DOM refs after DOMContentLoaded (script at end body, module defer so DOM ready). Use direct query.

Screen switching:
```js
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active', s.id===id));
  G.screen = id;
  if (id==='battle') requestAnimationFrame(resizeBoard);
}
```

Home:
```js
function initHome() {
  const p = loadProgress();
  const btn = $('#btn-continue');
  if (p) { btn.disabled=false; btn.textContent = `Continue · Stage ${p.stageIndex+1}`; } else { btn.disabled=true; btn.textContent='Continue'; }
  ...
}
```
If saved stageIndex >= STAGES.length (shouldn't), treat no save.

New run:
```js
function newRun() {
  if (loadProgress()) { confirm sheet... } else startNewRun();
}
function startNewRun() {
  G.upgrades={atk:0,hp:0,move:0};
  G.stageIndex=0;
  G.runTurns=0;
  saveProgress();
  startStage(0);
}
```

Confirm overlay:
```js
function confirmSheet({title, text, confirm, cancel, danger, onConfirm}) { ... }
```
Keep simple.

startStage(index):
```js
function startStage(index) {
  G.token++;
  G.stageIndex = index;
  G.turn = 1;
  G.phase='player';
  G.busy=false;
  G.selectedId=null;
  G.activeEnemyId=null;
  G.floaters=[];
  G.shake=0;
  G.units=[];
  G.stats={fallen:0};
  G.runTurns = 0? no, track separately.
  const heroes = index >= 1 ? ['warden','hexblade','ranger'] : ['warden','ranger'];
  const spawns = heroes.length===3 ? [[1,5],[2,4],[4,5]] : [[2,5],[3,4]];
  heroes.forEach((t,i)=> G.units.push(createHero(t, ...spawns[i])));
  STAGES[index].enemies.forEach(([type,x,y])=>G.units.push(createEnemy(type,x,y)));
  // ensure unique ids
  showScreen('battle');
  updateHUD();
  updateStrip();
  saveProgress();
  resizeBoard();
  banner('YOUR TURN');
  selectHero(firstReadyHero()?.id, true);
  updateHint();
  sfx('turn');
}
```
Wait `createHero` uses G.upgrades. Fine.

Full heal each stage (created with maxHp).

`saveProgress` includes stageIndex, upgrades, maybe `unlocked` not needed since stage>=1 implies hexblade. Save `{stageIndex, upgrades, runTurns}`.

`updateHUD`: stage count, name, turn, enemies remaining, objective. e.g. objective "Slay all foes · 3 remain" or during enemy "Enemy turn". Maybe:
```js
$('#hud-objective').textContent = G.phase==='enemy' ? 'The dead move…' : `${enemiesAlive()} foes remain`;
```
And turn "Turn N". Good.

`updateStrip` builds hero cards. Since only 3 heroes, rebuilding innerHTML each time is fine; but transitions/click handlers need rebinding. Use event delegation on container. Simpler: rebuild with data-id and delegate click. Do that.

```js
function updateStrip() {
  const heroes = G.units.filter(u=>u.side==='hero');
  strip.innerHTML = heroes.map(h=>{
    const ratio = h.hp/h.maxHp;
    const cls = !h.alive?'fallen': h.spent?'spent': G.selectedId===h.id?'selected':'';
    const state = !h.alive?'Fallen': h.spent?'Done': h.moved&&!h.attacked?'Moved': h.attacked?'Struck':'Ready';
    const hpCls = ratio<=.34?'low':ratio<=.66?'mid':'';
    return `<button class="hero-card ${cls}" data-hero="${h.id}" ${h.alive?'':'disabled'}>
      <div class="hc-top"><span class="hc-name">${h.name}</span><span class="hc-hpnum">${h.hp}/${h.maxHp}</span></div>
      <div class="hc-bar"><i class="${hpCls}" style="width:${Math.max(0,ratio*100)}%"></i></div>
      <div class="hc-state">${state}</div>
    </button>`;
  }).join('');
  // done button state
  const sel = selectedHero();
  doneBtn.disabled = !sel || G.phase!=='player' || G.busy;
}
```
Need esc? names static. Fine.

`updateHint`:
- if phase enemy: "The dead take their turn…"
- if busy: "…"
- if selected hero:
  - if can move and targets exist: "Tap a teal tile or a marked foe"
  - if can move only: "Tap a teal tile to move"
  - if targets only: "Tap a marked foe to attack"
  - if neither: "Tap Done to finish this hero"
- else if all spent: "End turn"
- else "Tap a hero"
Also hide hint after some time? Keep visible; it's useful. Maybe subtle. I'll keep, updating contextually.

`selectedHero()` returns unit by selectedId alive.

`firstReadyHero()` alive && !spent.

`selectHero(id, silent)`:
```js
if (G.phase!=='player' || G.busy) return;
const h = G.units.find(u=>u.id===id);
if (!h || !h.alive || h.spent) return;
G.selectedId = id;
sfx('tap');
updateStrip(); updateHint();
```
If tapping already selected hero, maybe deselect? No.

`canMoveTo` uses cached move set. We can compute on the fly each tap. BFS 6x6 trivial.

`computeMoveSet(hero)`:
```js
if (hero.moved || hero.attacked) return new Map();
const blocked = new Set(alive units except hero -> key)
BFS; dist 0..move; only pass through nonblocked; return map of key->dist excluding start.
```
Should enemies block movement? yes. Should heroes pass through allies? no.

`computeTargets(hero)`:
```js
if (hero.attacked) return [];
return enemies alive within manhattan <= hero.range
```
Could add line of sight? no.

Rendering highlight state computed each frame or on change? Compute each frame is fine for 36 tiles but allocations. Cache in `G.highlight = {moves:Set, targets:Set}` updated on selection/action changes. Simpler: compute each draw; 36 tiles and BFS each frame is wasteful but negligible (36 nodes). Still, avoid BFS every frame: cache `G.moveSet` and `G.targetSet`, call `refreshSelection()` when state changes (select, move, attack, turn). Draw reads cache. Do that.

`refreshSelection()`:
```js
const h = selectedHero();
G.moveSet = h ? computeMoveSet(h) : new Map();
G.targetSet = new Set(h ? computeTargets(h).map(u=>u.id) : []);
```
Enemy ids numeric too. Set of ids.

`onBoardTap`:
```js
if (G.screen!=='battle' || G.phase!=='player' || G.busy) return;
const cell = pointToCell(e);
const u = unitAt(cell.x, cell.y);
const h = selectedHero();
if (u && u.alive && u.side==='hero') { selectHero(u.id); return; }
if (!h) { if (u && u.side==='enemy') toast(`${u.name}: ${u.hp}/${u.maxHp} HP`); return; }
if (u && u.alive && u.side==='enemy') {
  if (G.targetSet.has(u.id)) attack(h,u);
  else toast(`${u.name} is out of range`);
  return;
}
if (u && !u.alive) return; // dying token
if (G.moveSet.has(key)) { moveHero(h, cell.x, cell.y); return; }
if (cell.x===h.x && cell.y===h.y) { toast(`${h.name} — ${h.hp}/${h.maxHp} HP · ATK ${h.atk}`); return; }
toast('Too far');
```

`moveHero`:
```js
async function moveHero(h,x,y) {
  if (G.busy) return;
  h.x=x; h.y=y; h.moved=true;
  sfx('move'); haptic(8);
  refreshSelection(); updateStrip(); updateHint();
  const targets = computeTargets(h);
  if (!targets.length) {
    await sleep(260);
    if (G.phase==='player' && !G.busy) finishHero(h);
  } else {
    toast('Foe in range — tap to strike');
  }
}
```
But `finishHero` selects next hero, which might confuse if the player wanted to move another. Auto is good.

`finishHero(h)`:
```js
h.spent = true;
if (G.selectedId===h.id) {
  G.selectedId = null;
  const next = firstReadyHero();
  if (next) { G.selectedId=next.id; } // select next
}
refreshSelection(); updateStrip(); updateHint();
if (!firstReadyHero()) { setTimeout(()=>{ if (G.phase==='player'&&!G.busy) endPlayerTurn(); }, 450); }
```
But if selected next, `refreshSelection` after setting. Good. Need ensure not auto-end if player wants to press Done? all spent -> end automatically.

Attack:
