```js
async function enemyAct(enemy, token) {
  const heroes = () => G.units.filter(u=>u.side==='hero'&&u.alive);
  if (!heroes().length) return;
  // attack if possible now
  let targets = heroes().filter(h=>dist(enemy,h)<=enemy.range);
  if (!targets.length) {
    // find best reachable tile
    const reach = computeReachable(enemy, true); // includes current
    let best = {x:enemy.x,y:enemy.y, score:Infinity, target:null};
    for (const [key] of reach) {
      const [x,y] = key.split(',').map(Number);
      const hs = heroes();
      let bestTarget = null, bestD = Infinity;
      for (const h of hs) { const d = Math.abs(h.x-x)+Math.abs(h.y-y); if (d<bestD) {bestD=d;bestTarget=h;} }
      const canHit = bestD <= enemy.range;
      const score = (canHit?0:100) + bestD*10 + (bestTarget? bestTarget.hp*0.1:0);
      // For melee, if multiple tiles same d, prefer staying? no.
      if (score < best.score) best = {x,y,score,target:bestTarget};
    }
    if (best.x!==enemy.x || best.y!==enemy.y) {
      enemy.x=best.x; enemy.y=best.y;
      sfx('step');
      await sleep(300);
      if (token!==G.token) return;
    }
    targets = heroes().filter(h=>dist(enemy,h)<=enemy.range);
  }
  if (!targets.length) return;
  // choose lowest hp, then nearest
  targets.sort((a,b)=> a.hp-b.hp || dist(enemy,a)-dist(enemy,b));
  const victim = targets[0];
  await sleep(180);
  if (token!==G.token) return;
  sfx('hurt'); haptic(14);
  damageUnit(victim, enemy.atk, enemy);
  if (victim.hp<=0) {
    G.stats.fallen++;
    if (G.selectedId===victim.id) G.selectedId=null;
    toast(`${victim.name} has fallen`);
  }
  updateStrip(); updateHUD();
  await sleep(380);
}
```

