function computeMoveSet(unit) {
  const out = new Map();
  if (!unit || !unit.alive || unit.moved || unit.attacked) return out;
  const blocked = new Set();
  for (const u of G.units) if (u.alive && u.id!==unit.id) blocked.add(`${u.x},${u.y}`);
  const startKey = `${unit.x},${unit.y}`;
  const dist = new Map([[startKey,0]]);
  const q=[[unit.x,unit.y,0]];
  while(q.length){ const [x,y,d]=q.shift(); if(d>=unit.move) continue; for dirs... { nx,ny in bounds; k; if(dist.has(k)||blocked.has(k)) continue; dist.set(k,d+1); out.set(k,d+1); q.push([nx,ny,d+1]); } }
  return out;
}
```
