function openOverlay(html) {
  if (!overlay) return;
  overlay.innerHTML = html;
  overlay.classList.remove('hidden');
}

function closeOverlay() {
  if (!overlay) return;
  overlay.classList.add('hidden');
  overlay.innerHTML = '';
}

function askNewRun() {
  if (!loadProgress()) {
    startNewRun();
    return;
  }
  openOverlay(`
    <div class="sheet">
      <p class="kicker">NEW RUN</p>
      <h2>Begin Again?</h2>
